2	//!
3	//! This module validates configuration for correctness:
4	//! - Steps must have either template or command
5	//! - depends_on must reference existing steps
6	//! - Workflows must reference existing steps
7	//! - No circular dependencies allowed
8	//! - Var names must be valid identifiers
9	//! - Var names must not collide with builtin variables
10	//! - Computed vars must have non-empty commands
11	
12	use crate::config::schema::{BivvyConfig, VarDefinition};
13	use crate::error::{BivvyError, Result};
14	use std::collections::HashSet;
15	
16	/// Built-in interpolation variable names that user vars must not shadow.
17	const BUILTIN_VAR_NAMES: &[&str] = &["bivvy_version", "project_name", "project_root"];
18	
19	/// Validation error with context.
20	#[derive(Debug, Clone)]
21	pub struct ValidationError {
22	    /// Rule identifier
23	    pub rule: String,
24	    /// Human-readable error message
25	    pub message: String,
26	    /// Step name if error is step-specific
27	    pub step: Option<String>,
28	    /// Workflow name if error is workflow-specific
29	    pub workflow: Option<String>,
30	}
31	
32	/// Validate a configuration and return all errors.
33	///
34	/// This function collects all validation errors rather than stopping
35	/// at the first one, allowing users to fix multiple issues at once.
36	pub fn validate_config(config: &BivvyConfig) -> Vec<ValidationError> {
37	    let mut errors = Vec::new();
38	
39	    errors.extend(validate_vars(config));
40	    errors.extend(validate_steps(config));
41	    errors.extend(validate_workflows(config));
42	    errors.extend(validate_dependencies(config));
43	
44	    errors
45	}
46	
47	/// Check whether a var name is a valid identifier.
48	///
49	/// Valid names start with a letter or underscore and contain only
50	/// ASCII letters, digits, and underscores.
51	fn is_valid_var_name(name: &str) -> bool {
52	    if name.is_empty() {
53	        return false;
54	    }
55	    let mut chars = name.chars();
56	    let first = chars.next().unwrap();
57	    if !first.is_ascii_alphabetic() && first != '_' {
58	        return false;
59	    }
60	    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
61	}
62	
63	/// Validate user-defined variable declarations.
64	fn validate_vars(config: &BivvyConfig) -> Vec<ValidationError> {
65	    let mut errors = Vec::new();
66	
67	    for (name, def) in &config.vars {
68	        // Empty or invalid var name
69	        if !is_valid_var_name(name) {
70	            errors.push(ValidationError {
71	                rule: "invalid-var-name".to_string(),
72	                message: format!(
73	                    "Variable '{}' has an invalid name. \
74	                     Names must start with a letter or underscore and \
75	                     contain only letters, digits, and underscores.",
76	                    name
77	                ),
78	                step: None,
79	                workflow: None,
80	            });
81	        }
82	
83	        // Collision with builtin variables
84	        if BUILTIN_VAR_NAMES.contains(&name.as_str()) {
85	            errors.push(ValidationError {
86	                rule: "builtin-var-collision".to_string(),
87	                message: format!(
88	                    "Variable '{}' collides with a built-in variable. \
89	                     Choose a different name.",
90	                    name
91	                ),
92	                step: None,
93	                workflow: None,
94	            });
95	        }
96	
97	        // Computed vars must have a non-empty command
98	        if let VarDefinition::Computed { command } = def {
99	            if command.trim().is_empty() {
100	                errors.push(ValidationError {
101	                    rule: "empty-var-command".to_string(),
102	                    message: format!("Computed variable '{}' has an empty command.", name),
103	                    step: None,
104	                    workflow: None,
105	                });
106	            }
107	        }
108	    }
109	
110	    errors
111	}
112	
113	/// Validate step definitions.
114	fn validate_steps(config: &BivvyConfig) -> Vec<ValidationError> {
115	    let mut errors = Vec::new();
116	
117	    for (name, step) in &config.steps {
118	        // Step must have either template or command
119	        if step.template.is_none() && step.execution.command.is_none() {
120	            errors.push(ValidationError {
121	                rule: "missing-command".to_string(),
122	                message: format!("Step '{}' must have either 'template' or 'command'", name),
123	                step: Some(name.clone()),
124	                workflow: None,
125	            });
126	        }
127	
128	        // Validate depends_on references
129	        for dep in &step.depends_on {
130	            if !config.steps.contains_key(dep) {
131	                errors.push(ValidationError {
132	                    rule: "unknown-step".to_string(),
133	                    message: format!("Step '{}' depends on '{}' which does not exist", name, dep),
134	                    step: Some(name.clone()),
135	                    workflow: None,
136	                });
137	            }
138	        }
139	    }
140	
141	    errors
142	}
143	
144	/// Validate workflow definitions.
145	fn validate_workflows(config: &BivvyConfig) -> Vec<ValidationError> {
146	    let mut errors = Vec::new();
147	
148	    for (name, workflow) in &config.workflows {
149	        // Validate step references
150	        for step_name in &workflow.steps {
151	            if !config.steps.contains_key(step_name) {
152	                errors.push(ValidationError {
153	                    rule: "unknown-workflow-step".to_string(),
154	                    message: format!(
155	                        "Workflow '{}' references step '{}' which does not exist",
156	                        name, step_name
157	                    ),
158	                    step: None,
159	                    workflow: Some(name.clone()),
160	                });
161	            }
162	        }
163	
164	        // Validate override references
165	        for step_name in workflow.overrides.keys() {
166	            if !workflow.steps.contains(step_name) {
167	                errors.push(ValidationError {
168	                    rule: "unknown-override-step".to_string(),
169	                    message: format!(
170	                        "Workflow '{}' has override for '{}' which is not in the workflow",
171	                        name, step_name
172	                    ),
173	                    step: None,
174	                    workflow: Some(name.clone()),
175	                });
176	            }
177	        }
178	    }
179	
180	    errors
181	}
182	
183	/// Validate step dependencies for cycles.
184	fn validate_dependencies(config: &BivvyConfig) -> Vec<ValidationError> {
185	    let mut errors = Vec::new();
186	    let mut visited = HashSet::new();
187	    let mut rec_stack = HashSet::new();
188	    let mut path = Vec::new();
189	
190	    for step_name in config.steps.keys() {
191	        if let Some(cycle) =
192	            detect_cycle(step_name, config, &mut visited, &mut rec_stack, &mut path)
193	        {
194	            errors.push(ValidationError {
195	                rule: "circular-dependency".to_string(),
196	                message: format!("Circular dependency detected: {}", cycle),
197	                step: Some(step_name.clone()),
198	                workflow: None,
199	            });
200	            break; // Only report one cycle
201	        }
202	    }
203	
204	    errors
205	}
206	
207	fn detect_cycle(
208	    step: &str,
209	    config: &BivvyConfig,
210	    visited: &mut HashSet<String>,
211	    rec_stack: &mut HashSet<String>,
212	    path: &mut Vec<String>,
213	) -> Option<String> {
214	    if rec_stack.contains(step) {
215	        // Found cycle - format it
216	        let cycle_start = path.iter().position(|s| s == step).unwrap();
217	        let cycle: Vec<_> = path[cycle_start..].to_vec();
218	        return Some(format!("{} -> {}", cycle.join(" -> "), step));
219	    }
220	
221	    if visited.contains(step) {
222	        return None;
223	    }
224	
225	    visited.insert(step.to_string());
226	    rec_stack.insert(step.to_string());
227	    path.push(step.to_string());
228	
229	    if let Some(step_config) = config.steps.get(step) {
230	        for dep in &step_config.depends_on {
231	            if let Some(cycle) = detect_cycle(dep, config, visited, rec_stack, path) {
232	                return Some(cycle);
233	            }
234	        }
235	    }
236	
237	    path.pop();
238	    rec_stack.remove(step);
239	    None
240	}
241	
242	/// Validate and return Result (for convenience).
243	///
244	/// # Errors
245	///
246	/// Returns `ConfigValidationError` if any validation rules fail.
247	pub fn validate(config: &BivvyConfig) -> Result<()> {
248	    let errors = validate_config(config);
249	
250	    if errors.is_empty() {
251	        Ok(())
252	    } else {
253	        let messages: Vec<_> = errors.iter().map(|e| e.message.clone()).collect();
254	        Err(BivvyError::ConfigValidationError {
255	            message: messages.join("; "),
256	        })
257	    }
258	}
