// --- Unknown field detection for structs using #[serde(flatten)] ---
//
// `Settings` and `StepConfig` use `#[serde(flatten)]` to keep the YAML
// surface flat. Serde's `deny_unknown_fields` is incompatible with
// `flatten`, so typos in these structs are silently ignored at runtime
// and the fields fall back to defaults. These functions detect unknown
// fields by comparing raw YAML keys against the known set.

fn known_settings_fields() -> HashSet<&'static str> {
    [
        // Settings direct
        "defaults",
        // LoggingSettings
        "logging",
        "log_retention_days",
        "log_retention_mb",
        // ExecutionSettings
        "parallel",
        "max_parallel",
        "history_retention",
        "diagnostic_funnel",
        "auto_update",
        "default_rerun_window",
        // EnvVarSettings
        "env",
        "env_file",
        "secret_env",
        // EnvironmentProfileSettings
        "default_environment",
        "environments",
    ]
    .into_iter()
    .collect()
}

fn known_step_fields() -> HashSet<&'static str> {
    [
        // StepConfig direct
        "template",
        "inputs",
        "title",
        "description",
        "depends_on",
        "tools",
        "requires",
        "satisfied_when",
        "watches",
        // ExecutionConfig
        "command",
        "check",
        "completed_check",
        "checks",
        "precondition",
        "retry",
        "requires_sudo",
        // EnvironmentVarsConfig
        "env",
        "env_file",
        "env_file_optional",
        "required_env",
        // BehaviorConfig
        "skippable",
        "required",
        "confirm",
        "auto_run",
        "prompt_on_rerun",
        "prompt_if_complete",
        "allow_failure",
        "sensitive",
        "rerun_window",
        "force",
        // HookConfig
        "before",
        "after",
        // StepOutputSettings
        "output",
        "prompts",
        // EnvironmentScopingConfig
        "environments",
        "only_environments",
    ]
    .into_iter()
    .collect()
}

/// Check a raw YAML config value for unknown fields in structs that use
/// `#[serde(flatten)]` (where serde cannot enforce `deny_unknown_fields`).
///
/// Returns a list of human-readable error messages, one per unknown field.
pub fn validate_unknown_fields(value: &Value) -> Vec<String> {
    let mut errors = Vec::new();

    let Some(root) = value.as_mapping() else {
        return errors;
    };

    if let Some(settings) = root
        .get(&Value::String("settings".to_string()))
        .and_then(|v| v.as_mapping())
    {
        let known = known_settings_fields();
        for key in settings.keys() {
            if let Some(key_str) = key.as_str() {
                if !known.contains(key_str) {
                    let suggestion = suggest_field(key_str, &known);
                    errors.push(format_unknown_field("settings", key_str, suggestion.as_deref()));
                }
            }
        }
    }

    if let Some(steps) = root
        .get(&Value::String("steps".to_string()))
        .and_then(|v| v.as_mapping())
    {
        let known = known_step_fields();
        for (step_name_val, step_value) in steps {
            if let (Some(name), Some(step_map)) = (step_name_val.as_str(), step_value.as_mapping())
            {
                for key in step_map.keys() {
                    if let Some(key_str) = key.as_str() {
                        if !known.contains(key_str) {
                            let suggestion = suggest_field(key_str, &known);
                            let path = format!("steps.{}", name);
                            errors.push(format_unknown_field(
                                &path,
                                key_str,
                                suggestion.as_deref(),
                            ));
                        }
                    }
                }
            }
        }
    }

    errors
}

fn format_unknown_field(path: &str, field: &str, suggestion: Option<&str>) -> String {
    match suggestion {
        Some(s) => format!("Unknown field '{}' in {}. Did you mean '{}'?", field, path, s),
        None => format!("Unknown field '{}' in {}", field, path),
    }
}

fn suggest_field(input: &str, known: &HashSet<&str>) -> Option<String> {
    let mut best: Option<(&str, usize)> = None;
    for &candidate in known {
        let dist = levenshtein(input, candidate);
        if dist <= 3 && dist < input.len() {
            if best.is_none() || dist < best.unwrap().1 {
                best = Some((candidate, dist));
            }
        }
    }
    best.map(|(s, _)| s.to_string())
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a_bytes = a.as_bytes();
    let b_bytes = b.as_bytes();
    let a_len = a_bytes.len();
    let b_len = b_bytes.len();

    let mut prev: Vec<usize> = (0..=b_len).collect();
    let mut curr = vec![0; b_len + 1];

    for i in 1..=a_len {
        curr[0] = i;
        for j in 1..=b_len {
            let cost = if a_bytes[i - 1] == b_bytes[j - 1] {
                0
            } else {
                1
            };
            curr[j] = (prev[j] + 1).min(curr[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }

    prev[b_len]
}

