    }

    #[test]
    fn unknown_field_in_step_detected() {
        let value = yaml(
            r#"
steps:
  install:
    comand: npm install
"#,
        );
        let errors = validate_unknown_fields(&value);
        assert_eq!(errors.len(), 1);
        assert!(errors[0].contains("comand"));
        assert!(errors[0].contains("steps.install"));
        assert!(errors[0].contains("command"));
    }

    #[test]
    fn unknown_field_in_settings_detected() {
        let value = yaml(
            r#"
settings:
  paralle: true
"#,
        );
        let errors = validate_unknown_fields(&value);
        assert_eq!(errors.len(), 1);
        assert!(errors[0].contains("paralle"));
        assert!(errors[0].contains("settings"));
        assert!(errors[0].contains("parallel"));
    }

    #[test]
    fn valid_step_fields_accepted() {
        let value = yaml(
            r#"
steps:
  install:
    command: npm install
    title: Install dependencies
    depends_on: []
    retry: 2
    env:
      NODE_ENV: production
    before:
      - echo starting
    skippable: false
"#,
        );
        let errors = validate_unknown_fields(&value);
        assert!(errors.is_empty());
    }

    #[test]
    fn valid_settings_fields_accepted() {
        let value = yaml(
            r#"
settings:
  parallel: true
  max_parallel: 8
  logging: false
  defaults:
    output: quiet
  env:
    GLOBAL: "yes"
"#,
        );
        let errors = validate_unknown_fields(&value);
        assert!(errors.is_empty());
    }

    #[test]
    fn multiple_unknown_fields_all_reported() {
        let value = yaml(
            r#"
steps:
  install:
    comand: npm install
    ttle: Install
"#,
        );
        let errors = validate_unknown_fields(&value);
        assert_eq!(errors.len(), 2);
    }

    #[test]
    fn unknown_field_no_suggestion_for_distant_typo() {
        let value = yaml(
            r#"
steps:
  install:
    xyz_not_a_field: true
"#,
        );
        let errors = validate_unknown_fields(&value);
        assert_eq!(errors.len(), 1);
        assert!(!errors[0].contains("Did you mean"));
    }

    #[test]
    fn non_mapping_root_returns_no_errors() {
        let value = yaml("42");
        let errors = validate_unknown_fields(&value);
        assert!(errors.is_empty());
    }

    #[test]
    fn config_without_steps_or_settings_returns_no_errors() {
        let value = yaml("app_name: test");
        let errors = validate_unknown_fields(&value);
        assert!(errors.is_empty());
    }

    #[test]
    fn levenshtein_distance() {
        assert_eq!(levenshtein("", ""), 0);
        assert_eq!(levenshtein("abc", "abc"), 0);
        assert_eq!(levenshtein("abc", "abd"), 1);
        assert_eq!(levenshtein("comand", "command"), 1);
        assert_eq!(levenshtein("paralle", "parallel"), 1);
        assert_eq!(levenshtein("abc", "xyz"), 3);
    }
}

