/// Deserialize a merged YAML value into [`BivvyConfig`], validating for
/// unknown fields first.
///
/// This centralizes the validate-then-deserialize pattern used by all
/// merge-based loaders.
fn deserialize_merged(merged: serde_yaml::Value, source_path: &Path) -> Result<BivvyConfig> {
    let unknown = crate::config::validator::validate_unknown_fields(&merged);
    if !unknown.is_empty() {
        return Err(BivvyError::ConfigParseError {
            path: source_path.to_path_buf(),
            message: unknown.join("; "),
        });
    }

    serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: format!("Failed to parse merged config: {}", e),
    })
}

